"""Tests for the smt_solver layer."""

import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from framework import PETERSEN_GRAPH, Graph
from smt_solver import (
    chromatic_number,
    coloring_model,
    count_nqueens_solutions,
    schedule_assignment,
    schedule_jobs,
)


class TestNQueens(unittest.TestCase):
    def test_known_counts(self):
        # Classic sequence: 1, 0, 0, 2, 10, 4, 40, 92
        self.assertEqual(count_nqueens_solutions(1), 1)
        self.assertEqual(count_nqueens_solutions(2), 0)
        self.assertEqual(count_nqueens_solutions(3), 0)
        self.assertEqual(count_nqueens_solutions(4), 2)
        self.assertEqual(count_nqueens_solutions(5), 10)
        self.assertEqual(count_nqueens_solutions(6), 4)

    def test_eight_queens(self):
        self.assertEqual(count_nqueens_solutions(8), 92)


class TestColoring(unittest.TestCase):
    def test_petersen_is_three_chromatic(self):
        self.assertEqual(chromatic_number(PETERSEN_GRAPH), 3)

    def test_triangle_and_bipartite(self):
        triangle = Graph([0, 1, 2], [(0, 1), (1, 2), (2, 0)])
        self.assertEqual(chromatic_number(triangle), 3)
        square = Graph([0, 1, 2, 3], [(0, 1), (1, 2), (2, 3), (3, 0)])
        self.assertEqual(chromatic_number(square), 2)
        edgeless = Graph([0, 1, 2], [])
        self.assertEqual(chromatic_number(edgeless), 1)

    def test_model_is_a_proper_coloring(self):
        model = coloring_model(PETERSEN_GRAPH, 3)
        self.assertIsNotNone(model)
        for u, v in PETERSEN_GRAPH.edges:
            self.assertNotEqual(model[u], model[v])
        self.assertIsNone(coloring_model(PETERSEN_GRAPH, 2))


class TestScheduling(unittest.TestCase):
    def test_reference_instance(self):
        jobs = [("A", 3), ("B", 5), ("C", 2), ("D", 4), ("E", 6), ("F", 1)]
        self.assertEqual(schedule_jobs(jobs, 3), 7)

    def test_single_machine_is_total_duration(self):
        jobs = [("A", 3), ("B", 5), ("C", 2)]
        self.assertEqual(schedule_jobs(jobs, 1), 10)

    def test_assignment_respects_machine_capacity(self):
        jobs = [("A", 3), ("B", 5), ("C", 2), ("D", 4), ("E", 6), ("F", 1)]
        makespan, plan = schedule_assignment(jobs, 3)
        self.assertEqual(makespan, 7)
        durations = dict(jobs)
        by_machine = {}
        for job_id, (start, machine) in plan.items():
            by_machine.setdefault(machine, []).append((start, durations[job_id]))
            self.assertLessEqual(start + durations[job_id], makespan)
        for intervals in by_machine.values():
            intervals.sort()
            for (s1, d1), (s2, _) in zip(intervals, intervals[1:]):
                self.assertLessEqual(s1 + d1, s2)

    def test_empty(self):
        self.assertEqual(schedule_jobs([], 3), 0)


if __name__ == "__main__":
    unittest.main()

