"""Tests for the fixedpoint / Datalog layer."""

import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from framework import CYCLIC_GRAPH_6, DIAMOND_DAG, Graph
from fixedpoint import (
    REACHING_DEFS_PROGRAM,
    analyze_reaching_definitions,
    check_horn_safety,
    count_reachable_pairs,
    reachable_pairs,
    reaching_definitions,
)


def bfs_reachable_pairs(graph):
    """Reference transitive closure computed without Z3."""
    adj = {n: set() for n in graph.nodes}
    for u, v in graph.edges:
        adj[u].add(v)
        if not graph.directed:
            adj[v].add(u)
    pairs = set()
    for src in graph.nodes:
        seen = set()
        stack = list(adj[src])
        while stack:
            node = stack.pop()
            if node in seen:
                continue
            seen.add(node)
            stack.extend(adj[node])
        for dst in seen:
            if dst != src:
                pairs.add((src, dst))
    return sorted(pairs)


class TestReachability(unittest.TestCase):
    def test_diamond_dag_matches_bfs(self):
        self.assertEqual(reachable_pairs(DIAMOND_DAG), bfs_reachable_pairs(DIAMOND_DAG))
        self.assertEqual(count_reachable_pairs(DIAMOND_DAG), 26)

    def test_cyclic_graph_is_strongly_connected(self):
        self.assertEqual(reachable_pairs(CYCLIC_GRAPH_6),
                         bfs_reachable_pairs(CYCLIC_GRAPH_6))
        self.assertEqual(count_reachable_pairs(CYCLIC_GRAPH_6), 30)

    def test_self_reachability_only_on_cycles(self):
        line = Graph([0, 1, 2], [(0, 1), (1, 2)], directed=True)
        self.assertEqual(reachable_pairs(line, include_self=True),
                         [(0, 1), (0, 2), (1, 2)])
        loop = Graph([0, 1], [(0, 1), (1, 0)], directed=True)
        self.assertEqual(reachable_pairs(loop, include_self=True),
                         [(0, 0), (0, 1), (1, 0), (1, 1)])

    def test_undirected_edges_go_both_ways(self):
        edge = Graph([0, 1], [(0, 1)], directed=False)
        self.assertEqual(count_reachable_pairs(edge), 2)


class TestHornSafety(unittest.TestCase):
    def test_expected_verdicts(self):
        self.assertEqual(check_horn_safety("counter_safe.smt2"), 1)
        self.assertEqual(check_horn_safety("two_var_safe.smt2"), 1)
        self.assertEqual(check_horn_safety("bakery_mutex.smt2"), 1)
        self.assertEqual(check_horn_safety("counter_unsafe.smt2"), 0)
        self.assertEqual(check_horn_safety("double_counter_unsafe.smt2"), 0)


class TestReachingDefinitions(unittest.TestCase):
    def test_reference_program(self):
        pairs = reaching_definitions(3, REACHING_DEFS_PROGRAM)
        # v0 defined at 0 -> reaches 0..4; v1 at 1 -> 1..4; v2 at 2 -> 2..4.
        expected = ([(p, 0) for p in range(5)]
                    + [(p, 1) for p in range(1, 5)]
                    + [(p, 2) for p in range(2, 5)])
        self.assertEqual(pairs, sorted(expected))
        self.assertEqual(analyze_reaching_definitions(3, REACHING_DEFS_PROGRAM), 12)

    def test_single_definition_propagates_forward(self):
        program = [(0, 0, []), (1, 0, [0]), (2, 0, [0])]
        self.assertEqual(analyze_reaching_definitions(1, program), 3)

    def test_late_definition_does_not_reach_backwards(self):
        program = [(0, 0, []), (1, 1, [])]
        pairs = reaching_definitions(2, program)
        self.assertNotIn((0, 1), pairs)
        self.assertIn((1, 0), pairs)

    def test_empty_program(self):
        self.assertEqual(analyze_reaching_definitions(3, []), 0)


if __name__ == "__main__":
    unittest.main()

