            body = expr.body()
            consts = [z3.Const(expr.var_name(i), expr.var_sort(i))
                      for i in range(expr.num_vars())]
            try:
                body = z3.substitute_vars(body, *reversed(consts))
            except z3.Z3Exception:  # pragma: no cover - defensive
                pass
            walk(body)
            return
        if not z3.is_app(expr):
            return
        if z3.is_eq(expr):
            lhs = expr.arg(0)
            if z3.is_app(lhs) and lhs.decl().kind() == z3.Z3_OP_UNINTERPRETED \
                    and lhs.sort() == z3.BoolSort():
                definitions.setdefault(lhs.decl().name(), expr.arg(1))
                return
        for i in range(expr.num_args()):
            walk(expr.arg(i))

    walk(answer)
    return definitions


def _extract_invariant(answer, relation):
    """Pull the definition of ``relation`` out of a Spacer answer expression.

    Returns a readable string, or ``str(answer)`` when the answer does not have
    the expected ``ForAll(vars, Inv(vars) == body)`` shape.
    """
    if answer is None:
        return None
    definition = extract_relation_definitions(answer).get(relation.name())
    if definition is None:
        return str(answer)
    return str(z3.simplify(definition))

input.content:
"""Translation of a small imperative language into constrained Horn clauses.

The pipeline is

    source text --parse_program--> SimpleAST --HornEncoder--> HornClause list
                --to_z3--> z3.Fixedpoint (Spacer) --query--> safe / unsafe

The encoding is the textbook control-flow-graph encoding: every program point
becomes an uninterpreted relation over the program variables, every statement
becomes a Horn clause relating the relation before it to the relation after it,
and every ``assert`` becomes a query clause into the ``Error`` relation.  A
``while`` loop becomes a recursive clause pair, so the invariant Spacer infers
for the loop relation *is* the loop invariant.

Grammar (whitespace insensitive, ``//`` starts a line comment)::

    program := stmt*
    stmt    := 'var' IDENT '=' expr ';'
             | IDENT '=' expr ';'
             | 'if' '(' expr ')' block ('else' (block | stmt))?
             | 'while' '(' expr ')' ('bound' NUM)? block
             | 'assert' '(' expr ')' ';'?
             | 'assume' '(' expr ')' ';'?
             | block
    block   := '{' stmt* '}'
    expr    := disjunction of conjunctions of (optionally negated) comparisons
               over +, -, * terms with the usual precedence
"""

import time

import z3

from spacer_verifier import extract_relation_definitions

__all__ = [
    # AST
    "Node", "Variable", "Const", "BinOp", "UnOp", "Assign", "If", "While",
    "Assert", "Assume", "Sequence", "collect_variables",
    # parser
    "Token", "tokenize", "Parser", "ParseError", "parse_program",
    # encoding
    "HornClause", "HornEncoder", "HornVerifier", "verify_program",
    "translate_program", "PROGRAMS",
]


# ===========================================================================
# 1. SimpleAST
# ===========================================================================

class Node(object):
    """Base class for all AST nodes."""

    def children(self):
        return []

    def __repr__(self):
        return self.__str__()


class Variable(Node):
    """Reference to a program variable."""

    def __init__(self, name):
        self.name = name

    def to_z3(self, env):
        if self.name not in env:
            raise KeyError("undeclared variable %r" % self.name)
        return env[self.name]

    def __str__(self):
        return self.name


class Const(Node):
    """Integer (or boolean) literal."""

    def __init__(self, value):
        self.value = value

    def to_z3(self, env):
        if isinstance(self.value, bool):
            return z3.BoolVal(self.value)
        return z3.IntVal(self.value)

    def __str__(self):
        return str(self.value)


class BinOp(Node):
    """Binary operation over two expressions."""

    ARITH = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
    }
    COMPARE = {
        "<": lambda a, b: a < b,
        "<=": lambda a, b: a <= b,
        "==": lambda a, b: a == b,
        "!=": lambda a, b: a != b,
        ">": lambda a, b: a > b,
        ">=": lambda a, b: a >= b,
    }
    LOGIC = {
        "and": lambda a, b: z3.And(a, b),
        "or": lambda a, b: z3.Or(a, b),
    }

    def __init__(self, op, left, right):
        if op not in self.ARITH and op not in self.COMPARE and op not in self.LOGIC:
            raise ValueError("unsupported binary operator %r" % op)
        self.op = op
        self.left = left
        self.right = right

    def children(self):
        return [self.left, self.right]

    def to_z3(self, env):
        left = self.left.to_z3(env)
        right = self.right.to_z3(env)
        if self.op in self.ARITH:
            return self.ARITH[self.op](left, right)
        if self.op in self.COMPARE:
            return self.COMPARE[self.op](left, right)
        return self.LOGIC[self.op](left, right)

    def __str__(self):
        return "(%s %s %s)" % (self.left, self.op, self.right)


class UnOp(Node):
    """Unary negation (``-``) or logical complement (``not``)."""

    def __init__(self, op, operand):
        if op not in ("-", "not"):
            raise ValueError("unsupported unary operator %r" % op)
        self.op = op
        self.operand = operand

    def children(self):
        return [self.operand]

    def to_z3(self, env):
        value = self.operand.to_z3(env)
        return -value if self.op == "-" else z3.Not(value)

    def __str__(self):
        return "(%s %s)" % (self.op, self.operand)


class Assign(Node):
    """``var_name = expr``."""

    def __init__(self, var_name, expr, declaration=False):
        self.var_name = var_name
        self.expr = expr
        self.declaration = declaration

    def children(self):
        return [self.expr]

    def __str__(self):
        return "%s%s = %s;" % ("var " if self.declaration else "",
                               self.var_name, self.expr)


class If(Node):
    """``if (cond) then_body else else_body``; ``else_body`` may be ``None``."""

    def __init__(self, cond, then_body, else_body=None):
        self.cond = cond
        self.then_body = then_body
        self.else_body = else_body

    def children(self):
        kids = [self.cond, self.then_body]
        if self.else_body is not None:
            kids.append(self.else_body)
        return kids

    def __str__(self):
        text = "if (%s) { %s }" % (self.cond, self.then_body)
        if self.else_body is not None:
            text += " else { %s }" % (self.else_body,)
        return text


class While(Node):
    """``while (cond) body`` with an optional iteration ``bound``."""

    def __init__(self, cond, body, bound=None):
        self.cond = cond
        self.body = body
        self.bound = bound

    def children(self):
        return [self.cond, self.body]

    def __str__(self):
        bound = "" if self.bound is None else " bound %d" % self.bound
        return "while (%s)%s { %s }" % (self.cond, bound, self.body)


class Assert(Node):
    """``assert(cond)`` -- the property to verify."""

    def __init__(self, cond):
        self.cond = cond

    def children(self):
        return [self.cond]

    def __str__(self):
        return "assert(%s);" % (self.cond,)


class Assume(Node):
    """``assume(cond)`` -- restrict the states considered afterwards."""

    def __init__(self, cond):
        self.cond = cond

    def children(self):
        return [self.cond]

    def __str__(self):
        return "assume(%s);" % (self.cond,)


class Sequence(Node):
    """Sequential composition."""

    def __init__(self, stmts):
        self.stmts = list(stmts)

    def children(self):
        return list(self.stmts)

    def __str__(self):
        return " ".join(str(s) for s in self.stmts)


def collect_variables(node, out=None):
    """Program variables in first-appearance order."""
    if out is None:
        out = []
    if isinstance(node, Variable):
        if node.name not in out:
            out.append(node.name)
    elif isinstance(node, Assign):
        if node.var_name not in out:
            out.append(node.var_name)
        collect_variables(node.expr, out)
        return out
    for child in node.children():
        collect_variables(child, out)
    return out


# ===========================================================================
# 2. Recursive-descent parser
# ===========================================================================

class ParseError(Exception):
    """Raised on malformed input programs."""


class Token(object):
    __slots__ = ("kind", "value", "line", "col")

    def __init__(self, kind, value, line, col):
        self.kind = kind      # 'num' | 'ident' | 'kw' | 'op' | 'eof'
        self.value = value
        self.line = line
        self.col = col

    def __repr__(self):
        return "Token(%s,%r,%d:%d)" % (self.kind, self.value, self.line, self.col)


KEYWORDS = {"var", "if", "else", "while", "assert", "assume", "bound",
            "and", "or", "not", "true", "false"}

# Longest operators first so that '<=' wins over '<'.
OPERATORS = ["<=", ">=", "==", "!=", "&&", "||", "<", ">", "=", "+", "-", "*",
             "!", "(", ")", "{", "}", ";", ","]


def tokenize(text):
    """Turn source ``text`` into a list of :class:`Token` (ending with ``eof``)."""
    tokens = []
    i, line, col = 0, 1, 1
    n = len(text)
    while i < n:
        ch = text[i]
        if ch == "\n":
            i, line, col = i + 1, line + 1, 1
            continue
        if ch.isspace():
            i, col = i + 1, col + 1
            continue
        if text.startswith("//", i):
            while i < n and text[i] != "\n":
                i += 1
            continue
        if text.startswith("/*", i):
            end = text.find("*/", i + 2)
            if end < 0:
                raise ParseError("unterminated block comment at line %d" % line)
            for c in text[i:end]:
                if c == "\n":
                    line, col = line + 1, 1
            i = end + 2
            continue
        if ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(Token("num", int(text[i:j]), line, col))
            col += j - i
            i = j
            continue
        if ch.isalpha() or ch == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            word = text[i:j]
            tokens.append(Token("kw" if word in KEYWORDS else "ident",
                                word, line, col))
            col += j - i
            i = j
            continue
        for op in OPERATORS:
            if text.startswith(op, i):
                tokens.append(Token("op", op, line, col))
                i += len(op)
                col += len(op)
                break
        else:
            raise ParseError("unexpected character %r at line %d col %d"
                             % (ch, line, col))
    tokens.append(Token("eof", None, line, col))
    return tokens


class Parser(object):
    """Recursive-descent parser for the imperative language."""

    def __init__(self, text):
        self.tokens = tokenize(text)
        self.pos = 0

    # -- token helpers ----------------------------------------------------
    @property
    def current(self):
        return self.tokens[self.pos]

    def at(self, kind, value=None):
        token = self.current
        return token.kind == kind and (value is None or token.value == value)

    def accept(self, kind, value=None):
        if self.at(kind, value):
            self.pos += 1
            return self.tokens[self.pos - 1]
        return None

    def expect(self, kind, value=None):
        token = self.accept(kind, value)
        if token is None:
            raise ParseError("expected %s%s but found %r at line %d col %d"
                             % (kind, "" if value is None else " %r" % (value,),
                                self.current.value, self.current.line,
                                self.current.col))
        return token

    # -- statements -------------------------------------------------------
    def parse_program(self):
        stmts = []
        while not self.at("eof"):
            stmts.append(self.parse_statement())
        if len(stmts) == 1 and isinstance(stmts[0], Sequence):
            return stmts[0]
        return Sequence(stmts)

    def parse_block(self):
        self.expect("op", "{")
        stmts = []
        while not self.at("op", "}"):
            if self.at("eof"):
                raise ParseError("unterminated block")
            stmts.append(self.parse_statement())
        self.expect("op", "}")
        return Sequence(stmts)

    def parse_body(self):
        """A block, or a single statement used as a body."""
        if self.at("op", "{"):
            return self.parse_block()
        return self.parse_statement()

    def parse_statement(self):
        if self.at("op", "{"):
            return self.parse_block()
        if self.at("op", ";"):
            self.pos += 1
            return Sequence([])
        if self.at("kw", "var"):
            self.pos += 1
            name = self.expect("ident").value
            self.expect("op", "=")
            expr = self.parse_expression()
            self.accept("op", ";")
            return Assign(name, expr, declaration=True)
        if self.at("kw", "if"):
            self.pos += 1
            self.expect("op", "(")
            cond = self.parse_expression()
            self.expect("op", ")")
            then_body = self.parse_body()
            else_body = None
            if self.accept("kw", "else"):
                else_body = self.parse_body()
            return If(cond, then_body, else_body)
        if self.at("kw", "while"):
            self.pos += 1
            self.expect("op", "(")
            cond = self.parse_expression()
            self.expect("op", ")")
            bound = None
            if self.accept("kw", "bound"):
                bound = self.expect("num").value
            body = self.parse_body()
            return While(cond, body, bound)
        if self.at("kw", "assert") or self.at("kw", "assume"):
            keyword = self.expect("kw").value
            self.expect("op", "(")
            cond = self.parse_expression()
            self.expect("op", ")")
            self.accept("op", ";")
            return Assert(cond) if keyword == "assert" else Assume(cond)
        if self.at("ident"):
            name = self.expect("ident").value
            self.expect("op", "=")
            expr = self.parse_expression()
            self.accept("op", ";")
            return Assign(name, expr)
        raise ParseError("unexpected token %r at line %d col %d"
                         % (self.current.value, self.current.line,
                            self.current.col))

    # -- expressions ------------------------------------------------------
    def parse_expression(self):
        return self.parse_or()

    def parse_or(self):
        node = self.parse_and()
        while self.at("kw", "or") or self.at("op", "||"):
            self.pos += 1
            node = BinOp("or", node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_not()
        while self.at("kw", "and") or self.at("op", "&&"):
            self.pos += 1
            node = BinOp("and", node, self.parse_not())
        return node

    def parse_not(self):
        if self.at("kw", "not") or self.at("op", "!"):
            self.pos += 1
            return UnOp("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        node = self.parse_additive()
        for op in ("<=", ">=", "==", "!=", "<", ">"):
            if self.at("op", op):
                self.pos += 1
                return BinOp(op, node, self.parse_additive())
        return node

    def parse_additive(self):
        node = self.parse_multiplicative()
        while self.at("op", "+") or self.at("op", "-"):
            op = self.expect("op").value
            node = BinOp(op, node, self.parse_multiplicative())
        return node

    def parse_multiplicative(self):
        node = self.parse_unary()
        while self.at("op", "*"):
            self.pos += 1
            node = BinOp("*", node, self.parse_unary())
        return node

    def parse_unary(self):
        if self.accept("op", "-"):
            return UnOp("-", self.parse_unary())
        if self.accept("op", "+"):
            return self.parse_unary()
        return self.parse_primary()

    def parse_primary(self):
        token = self.accept("num")
        if token is not None:
            return Const(token.value)
        if self.accept("kw", "true"):
            return Const(True)
        if self.accept("kw", "false"):
            return Const(False)
        token = self.accept("ident")
        if token is not None:
            return Variable(token.value)
        if self.accept("op", "("):
            node = self.parse_expression()
            self.expect("op", ")")
            return node
        raise ParseError("unexpected token %r at line %d col %d"
                         % (self.current.value, self.current.line,
                            self.current.col))


def parse_program(text):
    """Parse ``text`` and return the AST (a :class:`Sequence`)."""
    return Parser(text).parse_program()


# ===========================================================================
# 3. Horn encoding
# ===========================================================================

class HornClause(object):
    """A Horn clause ``body_1 /\\ ... /\\ body_n -> head``."""

    def __init__(self, head, body=None, label=""):
        self.head = head
        self.body = list(body or [])
        self.label = label

    def to_z3(self):
        """The clause as a single Z3 implication (useful for printing/tests)."""
        if not self.body:
            return self.head
        return z3.Implies(z3.And(*self.body) if len(self.body) > 1
                          else self.body[0], self.head)

    def __str__(self):
        body = " /\\ ".join(str(b) for b in self.body) or "true"
        return "%s -> %s%s" % (body, self.head,
                               "   // %s" % self.label if self.label else "")

    def __repr__(self):
        return "HornClause(%s)" % self


class HornEncoder(object):
    """Encode a :class:`Sequence` AST into constrained Horn clauses.

    Every program point becomes a relation ``p<k>`` over the program variables.
    ``self.clauses`` accumulates :class:`HornClause` objects; ``to_z3`` loads
    them into a :class:`z3.Fixedpoint`.
    """

    def __init__(self, program_vars=None, unroll_bounded=False):
        self.program_vars = list(program_vars or [])
        self.unroll_bounded = unroll_bounded
        self.clauses = []
        self.relations = []
        self.loop_relations = []
        self.entry_relation = None
        self.exit_relation = None
        self._counter = 0
        self._error = z3.Function("Error", z3.BoolSort())
        self._pre = []
        self._post = []

    # -- plumbing ---------------------------------------------------------
    def error(self):
        """The 0-ary ``Error`` relation queried to decide safety."""
        return self._error

    def _setup_vars(self):
        self._pre = [z3.Int(name) for name in self.program_vars]
        self._post = [z3.Int(name + "!next") for name in self.program_vars]

    @property
    def pre_vars(self):
        return list(self._pre)

    @property
    def post_vars(self):
        return list(self._post)

    def new_relation(self, prefix="p"):
        """Declare a fresh program-point relation over the program variables."""
        name = "%s%d" % (prefix, self._counter)
        self._counter += 1
        sorts = [z3.IntSort()] * len(self.program_vars) + [z3.BoolSort()]
        relation = z3.Function(name, *sorts)
        self.relations.append(relation)
        return relation

    def _env(self, variables):
        return dict(zip(self.program_vars, variables))

    def _frame(self, updated=None):
        """Equalities ``x!next == x`` for every variable except ``updated``."""
        return [post == pre
                for name, pre, post in zip(self.program_vars, self._pre, self._post)
                if name != updated]

    def _add(self, head, body, label=""):
        clause = HornClause(head, body, label)
        self.clauses.append(clause)
        return clause

    def _cond(self, expr, variables):
        value = expr.to_z3(self._env(variables))
        if z3.is_int(value) or (hasattr(value, "sort") and value.sort() == z3.IntSort()):
            # Allow C-style "non-zero is true" conditions.
            return value != 0
        return value

    # -- statement dispatch ----------------------------------------------
    def encode_program(self, ast):
        """Encode ``ast`` and return the list of :class:`HornClause` objects."""
        if not self.program_vars:
            self.program_vars = collect_variables(ast)
        self._setup_vars()
        self.clauses = []
        self.relations = []
        self.loop_relations = []
        self._counter = 0

        entry = self.new_relation("p_entry")
        self.entry_relation = entry
        # All variables start at 0 before the first statement runs.
        self._add(entry(*self._pre), [var == 0 for var in self._pre], "entry")
        self.exit_relation = self.encode_statement(ast, entry)
        return self.clauses

    def encode_statement(self, stmt, pre_rel):
        """Encode ``stmt`` starting from ``pre_rel``; return the post relation."""
        if isinstance(stmt, Sequence):
            current = pre_rel
            for sub in stmt.stmts:
                current = self.encode_statement(sub, current)
            return current
        if isinstance(stmt, Assign):
            post_rel = self.new_relation("p")
            self.encode_assignment(stmt, pre_rel, post_rel)
            return post_rel
        if isinstance(stmt, If):
            post_rel = self.new_relation("p")
            self.encode_branch(stmt, pre_rel, post_rel)
            return post_rel
        if isinstance(stmt, While):
            loop_rel = self.new_relation("loop")
            self.loop_relations.append(loop_rel)
            return self.encode_loop(stmt, loop_rel, pre_rel)
        if isinstance(stmt, Assert):
            self.encode_assertion(stmt, pre_rel)
            post_rel = self.new_relation("p")
            self._add(post_rel(*self._pre),
                      [pre_rel(*self._pre), self._cond(stmt.cond, self._pre)],
                      "assert-holds")
            return post_rel
        if isinstance(stmt, Assume):
            post_rel = self.new_relation("p")
            self._add(post_rel(*self._pre),
                      [pre_rel(*self._pre), self._cond(stmt.cond, self._pre)],
                      "assume")
            return post_rel
        raise TypeError("cannot encode statement %r" % (stmt,))

    # -- individual constructs -------------------------------------------
    def encode_assignment(self, assign, pre_rel, post_rel):
        """``pre_rel(X) /\\ X' = X[v := e] -> post_rel(X')``."""
        if assign.var_name not in self.program_vars:
            raise KeyError("assignment to unknown variable %r" % assign.var_name)
        index = self.program_vars.index(assign.var_name)
        value = assign.expr.to_z3(self._env(self._pre))
        body = [pre_rel(*self._pre), self._post[index] == value]
        body.extend(self._frame(updated=assign.var_name))
        return self._add(post_rel(*self._post), body,
                         "assign %s" % assign.var_name)

    def encode_branch(self, if_node, pre_rel, post_rel):
        """Two paths: ``cond /\\ then_body`` and ``~cond /\\ else_body``."""
        cond = self._cond(if_node.cond, self._pre)

        then_entry = self.new_relation("then")
        self._add(then_entry(*self._pre), [pre_rel(*self._pre), cond],
                  "if-then-guard")
        then_exit = self.encode_statement(if_node.then_body, then_entry)
        self._add(post_rel(*self._pre), [then_exit(*self._pre)], "if-then-join")

        else_entry = self.new_relation("else")
        self._add(else_entry(*self._pre), [pre_rel(*self._pre), z3.Not(cond)],
                  "if-else-guard")
        if if_node.else_body is None:
            else_exit = else_entry
        else:
            else_exit = self.encode_statement(if_node.else_body, else_entry)
        self._add(post_rel(*self._pre), [else_exit(*self._pre)], "if-else-join")
        return post_rel

    def encode_loop(self, while_node, loop_rel, pre_rel=None, post_rel=None):
        """Recursive clause pair for a ``while`` loop.

        ``pre_rel(X) -> loop_rel(X)`` (entry), ``loop_rel(X) /\\ cond /\\ body ->
        loop_rel(X')`` (back edge, via the body's clauses) and
        ``loop_rel(X) /\\ ~cond -> post_rel(X)`` (exit).

        When the encoder was built with ``unroll_bounded=True`` and the loop
        carries a ``bound``, the loop is unrolled that many times instead, which
        yields an under-approximation useful for bug hunting.
        """
        if pre_rel is None:
            pre_rel = self.new_relation("p_pre")
            self._add(pre_rel(*self._pre), [], "loop-entry-any")
        if post_rel is None:
            post_rel = self.new_relation("p")
        cond = self._cond(while_node.cond, self._pre)

        if self.unroll_bounded and while_node.bound is not None:
            current = pre_rel
            for k in range(while_node.bound):
                body_entry = self.new_relation("body")
                self._add(body_entry(*self._pre), [current(*self._pre), cond],
                          "unroll-%d-guard" % k)
                body_exit = self.encode_statement(while_node.body, body_entry)
                self._add(post_rel(*self._pre), [current(*self._pre),
                                                 z3.Not(cond)],
                          "unroll-%d-exit" % k)
                current = body_exit
            self._add(post_rel(*self._pre), [current(*self._pre)],
                      "unroll-cutoff")
            return post_rel

        self._add(loop_rel(*self._pre), [pre_rel(*self._pre)], "loop-entry")
        body_entry = self.new_relation("body")
        self._add(body_entry(*self._pre), [loop_rel(*self._pre), cond],
                  "loop-guard")
        body_exit = self.encode_statement(while_node.body, body_entry)
        self._add(loop_rel(*self._pre), [body_exit(*self._pre)], "loop-back")
        self._add(post_rel(*self._pre), [loop_rel(*self._pre), z3.Not(cond)],
                  "loop-exit")
        return post_rel

    def encode_assertion(self, assert_node, pre_rel):
        """``pre_rel(X) /\\ ~cond -> Error``."""
        cond = self._cond(assert_node.cond, self._pre)
        return self._add(self._error(),
                         [pre_rel(*self._pre), z3.Not(cond)], "assert")

    # -- Z3 hand-off ------------------------------------------------------
    def to_z3(self, program_vars=None, engine="spacer"):
        """Load every encoded clause into a fresh :class:`z3.Fixedpoint`."""
        if program_vars is not None and list(program_vars) != self.program_vars:
            raise ValueError("program_vars %r do not match the encoded program %r"
                             % (list(program_vars), self.program_vars))
        fp = z3.Fixedpoint()
        fp.set(engine=engine)
        fp.register_relation(*(self.relations + [self._error]))
        if self._pre or self._post:
            fp.declare_var(*(self._pre + self._post))
        for clause in self.clauses:
            if clause.body:
                fp.rule(clause.head, clause.body)
            else:
                fp.rule(clause.head)
        return fp

    def validate_clauses(self):
        """Sanity-check every clause; returns the number of clauses checked.

        A clause whose body is unsatisfiable can never fire, which almost always
        means the encoding is wrong, so the check catches encoder bugs early.
        Relation applications are replaced by ``True`` since only the arithmetic
        part of the body is checked.
        """
        solver = z3.Solver()
        checked = 0
        for clause in self.clauses:
            constraints = [b for b in clause.body if not self._is_relation(b)]
            solver.push()
            solver.add(*constraints)
            if solver.check() == z3.unsat:
                solver.pop()
                raise AssertionError("clause body is unsatisfiable: %s" % clause)
            solver.pop()
            checked += 1
        return checked

    def _is_relation(self, expr):
        if not z3.is_app(expr):
            return False
        decl = expr.decl()
        return decl.kind() == z3.Z3_OP_UNINTERPRETED \
            and decl.range() == z3.BoolSort()

    @property
    def num_clauses(self):
        return len(self.clauses)

    @property
    def num_relations(self):
        # Program-point relations plus the Error relation.
        return len(self.relations) + 1


# ===========================================================================
# 4. Verification front-end
# ===========================================================================

def translate_program(text, unroll_bounded=False):
    """Parse and encode ``text``; return ``(ast, encoder)``."""
    ast = parse_program(text)
    encoder = HornEncoder(unroll_bounded=unroll_bounded)
    encoder.encode_program(ast)
    return ast, encoder


class HornVerifier(object):
    """Translate an imperative program and decide its safety with Spacer."""

    def __init__(self, text, unroll_bounded=False):
        self.text = text
        self.unroll_bounded = unroll_bounded
        self.ast = None
        self.encoder = None
        self.fp = None
        self.answer = None

    def translate(self):
        """Parse + encode + build the Z3 fixedpoint (no solving yet)."""
        self.ast, self.encoder = translate_program(self.text, self.unroll_bounded)
        self.encoder.validate_clauses()
        self.fp = self.encoder.to_z3()
        return self.encoder

    def verify(self):
        """Return ``{"safe", "num_clauses", "num_relations", ...}``."""
        if self.encoder is None:
            self.translate()
        result = self.fp.query(self.encoder.error())
        safe = result == z3.unsat
        invariants = {}
        if safe:
            try:
                self.answer = self.fp.get_answer()
                definitions = extract_relation_definitions(self.answer)
            except z3.Z3Exception:  # pragma: no cover - defensive
                definitions = {}
            for relation in self.encoder.loop_relations:
                definition = definitions.get(relation.name())
                if definition is not None:
                    invariants[relation.name()] = str(z3.simplify(definition))
        return {
            "safe": safe,
            "result": str(result),
            "num_clauses": self.encoder.num_clauses,
            "num_relations": self.encoder.num_relations,
            "num_loops": len(self.encoder.loop_relations),
            "loop_invariants": invariants,
            "variables": list(self.encoder.program_vars),
        }


def verify_program(text):
    """Parse, encode and verify an imperative program in one call."""
    return HornVerifier(text).verify()


# ===========================================================================
# 5. Benchmark programs
# ===========================================================================

PROGRAMS = [
    ("simple_counter", """
        // count up to ten, then check we landed exactly on ten
        var x = 0;
        while (x < 10) { x = x + 1; }
        assert(x == 10)
    """),
    ("sum_accumulator", """
        var s = 0;
        var i = 0;
        while (i < 5) {
            s = s + i;
            i = i + 1;
        }
        assert(s >= 0)
    """),
    ("branch_test", """
        var x = 5;
        if (x > 3) { x = x - 1; } else { x = x + 1; }
        assert(x >= 0)
    """),
    ("unsafe_loop", """
        // x leaves the loop at 100, so x < 50 must fail
        var x = 0;
        while (x < 100) { x = x + 2; }
        assert(x < 50)
    """),
    ("nested_arithmetic", """
        var a = 1;
        var b = 2;
        a = a + b;
        b = a * 2;
        assert(b == 6)
    """),
]


def run_translation_batch(programs=None):
    """Translate and verify every program, returning a metrics dictionary."""
    programs = PROGRAMS if programs is None else programs
    total_clauses = 0
    verified = 0
    unsafe = 0
    invariants = 0
    translation_time = 0.0
    details = []

    for name, text in programs:
        verifier = HornVerifier(text)
        start = time.time()
        encoder = verifier.translate()
        translation_time += time.time() - start
        total_clauses += encoder.num_clauses

        result = verifier.verify()
        if result["safe"]:
            verified += 1
        else:
            unsafe += 1
        invariants += len(result["loop_invariants"])
        result["name"] = name
        details.append(result)

    return {
        "HORN_CLAUSES_GENERATED": total_clauses,
        "HORN_PROGRAMS_VERIFIED": verified,
        "HORN_PROGRAMS_UNSAFE": unsafe,
        "HORN_LOOP_INVARIANTS": invariants,
        "HORN_TRANSLATION_TIME": round(translation_time, 2),
        "details": details,
    }

toolUseResult.content:
"""Translation of a small imperative language into constrained Horn clauses.

The pipeline is

    source text --parse_program--> SimpleAST --HornEncoder--> HornClause list
                --to_z3--> z3.Fixedpoint (Spacer) --query--> safe / unsafe

The encoding is the textbook control-flow-graph encoding: every program point
becomes an uninterpreted relation over the program variables, every statement
becomes a Horn clause relating the relation before it to the relation after it,
and every ``assert`` becomes a query clause into the ``Error`` relation.  A
``while`` loop becomes a recursive clause pair, so the invariant Spacer infers
for the loop relation *is* the loop invariant.

Grammar (whitespace insensitive, ``//`` starts a line comment)::

    program := stmt*
    stmt    := 'var' IDENT '=' expr ';'
             | IDENT '=' expr ';'
             | 'if' '(' expr ')' block ('else' (block | stmt))?
             | 'while' '(' expr ')' ('bound' NUM)? block
             | 'assert' '(' expr ')' ';'?
             | 'assume' '(' expr ')' ';'?
             | block
    block   := '{' stmt* '}'
    expr    := disjunction of conjunctions of (optionally negated) comparisons
               over +, -, * terms with the usual precedence
"""

import time

import z3

from spacer_verifier import extract_relation_definitions

__all__ = [
    # AST
    "Node", "Variable", "Const", "BinOp", "UnOp", "Assign", "If", "While",
    "Assert", "Assume", "Sequence", "collect_variables",
    # parser
    "Token", "tokenize", "Parser", "ParseError", "parse_program",
    # encoding
    "HornClause", "HornEncoder", "HornVerifier", "verify_program",
    "translate_program", "PROGRAMS",
]


# ===========================================================================
# 1. SimpleAST
# ===========================================================================

class Node(object):
    """Base class for all AST nodes."""

    def children(self):
        return []

    def __repr__(self):
        return self.__str__()


class Variable(Node):
    """Reference to a program variable."""

    def __init__(self, name):
        self.name = name

    def to_z3(self, env):
        if self.name not in env:
            raise KeyError("undeclared variable %r" % self.name)
        return env[self.name]

    def __str__(self):
        return self.name


class Const(Node):
    """Integer (or boolean) literal."""

    def __init__(self, value):
        self.value = value

    def to_z3(self, env):
        if isinstance(self.value, bool):
            return z3.BoolVal(self.value)
        return z3.IntVal(self.value)

    def __str__(self):
        return str(self.value)


class BinOp(Node):
    """Binary operation over two expressions."""

    ARITH = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
    }
    COMPARE = {
        "<": lambda a, b: a < b,
        "<=": lambda a, b: a <= b,
        "==": lambda a, b: a == b,
        "!=": lambda a, b: a != b,
        ">": lambda a, b: a > b,
        ">=": lambda a, b: a >= b,
    }
    LOGIC = {
        "and": lambda a, b: z3.And(a, b),
        "or": lambda a, b: z3.Or(a, b),
    }

    def __init__(self, op, left, right):
        if op not in self.ARITH and op not in self.COMPARE and op not in self.LOGIC:
            raise ValueError("unsupported binary operator %r" % op)
        self.op = op
        self.left = left
        self.right = right

    def children(self):
        return [self.left, self.right]

    def to_z3(self, env):
        left = self.left.to_z3(env)
        right = self.right.to_z3(env)
        if self.op in self.ARITH:
            return self.ARITH[self.op](left, right)
        if self.op in self.COMPARE:
            return self.COMPARE[self.op](left, right)
        return self.LOGIC[self.op](left, right)

    def __str__(self):
        return "(%s %s %s)" % (self.left, self.op, self.right)


class UnOp(Node):
    """Unary negation (``-``) or logical complement (``not``)."""

    def __init__(self, op, operand):
        if op not in ("-", "not"):
            raise ValueError("unsupported unary operator %r" % op)
        self.op = op
        self.operand = operand

    def children(self):
        return [self.operand]

    def to_z3(self, env):
        value = self.operand.to_z3(env)
        return -value if self.op == "-" else z3.Not(value)

    def __str__(self):
        return "(%s %s)" % (self.op, self.operand)


class Assign(Node):
    """``var_name = expr``."""

    def __init__(self, var_name, expr, declaration=False):
        self.var_name = var_name
        self.expr = expr
        self.declaration = declaration

    def children(self):
        return [self.expr]

    def __str__(self):
        return "%s%s = %s;" % ("var " if self.declaration else "",
                               self.var_name, self.expr)


class If(Node):
    """``if (cond) then_body else else_body``; ``else_body`` may be ``None``."""

    def __init__(self, cond, then_body, else_body=None):
        self.cond = cond
        self.then_body = then_body
        self.else_body = else_body

    def children(self):
        kids = [self.cond, self.then_body]
        if self.else_body is not None:
            kids.append(self.else_body)
        return kids

    def __str__(self):
        text = "if (%s) { %s }" % (self.cond, self.then_body)
        if self.else_body is not None:
            text += " else { %s }" % (self.else_body,)
        return text


class While(Node):
    """``while (cond) body`` with an optional iteration ``bound``."""

    def __init__(self, cond, body, bound=None):
        self.cond = cond
        self.body = body
        self.bound = bound

    def children(self):
        return [self.cond, self.body]

    def __str__(self):
        bound = "" if self.bound is None else " bound %d" % self.bound
        return "while (%s)%s { %s }" % (self.cond, bound, self.body)


class Assert(Node):
    """``assert(cond)`` -- the property to verify."""

    def __init__(self, cond):
        self.cond = cond

    def children(self):
        return [self.cond]

    def __str__(self):
        return "assert(%s);" % (self.cond,)


class Assume(Node):
    """``assume(cond)`` -- restrict the states considered afterwards."""

    def __init__(self, cond):
        self.cond = cond

    def children(self):
        return [self.cond]

    def __str__(self):
        return "assume(%s);" % (self.cond,)


class Sequence(Node):
    """Sequential composition."""

    def __init__(self, stmts):
        self.stmts = list(stmts)

    def children(self):
        return list(self.stmts)

    def __str__(self):
        return " ".join(str(s) for s in self.stmts)


def collect_variables(node, out=None):
    """Program variables in first-appearance order."""
    if out is None:
        out = []
    if isinstance(node, Variable):
        if node.name not in out:
            out.append(node.name)
    elif isinstance(node, Assign):
        if node.var_name not in out:
            out.append(node.var_name)
        collect_variables(node.expr, out)
        return out
    for child in node.children():
        collect_variables(child, out)
    return out


# ===========================================================================
# 2. Recursive-descent parser
# ===========================================================================

class ParseError(Exception):
    """Raised on malformed input programs."""


class Token(object):
    __slots__ = ("kind", "value", "line", "col")

    def __init__(self, kind, value, line, col):
        self.kind = kind      # 'num' | 'ident' | 'kw' | 'op' | 'eof'
        self.value = value
        self.line = line
        self.col = col

    def __repr__(self):
        return "Token(%s,%r,%d:%d)" % (self.kind, self.value, self.line, self.col)


KEYWORDS = {"var", "if", "else", "while", "assert", "assume", "bound",
            "and", "or", "not", "true", "false"}

# Longest operators first so that '<=' wins over '<'.
OPERATORS = ["<=", ">=", "==", "!=", "&&", "||", "<", ">", "=", "+", "-", "*",
             "!", "(", ")", "{", "}", ";", ","]


def tokenize(text):
    """Turn source ``text`` into a list of :class:`Token` (ending with ``eof``)."""
    tokens = []
    i, line, col = 0, 1, 1
    n = len(text)
    while i < n:
        ch = text[i]
        if ch == "\n":
            i, line, col = i + 1, line + 1, 1
            continue
        if ch.isspace():
            i, col = i + 1, col + 1
            continue
        if text.startswith("//", i):
            while i < n and text[i] != "\n":
                i += 1
            continue
        if text.startswith("/*", i):
            end = text.find("*/", i + 2)
            if end < 0:
                raise ParseError("unterminated block comment at line %d" % line)
            for c in text[i:end]:
                if c == "\n":
                    line, col = line + 1, 1
            i = end + 2
            continue
        if ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(Token("num", int(text[i:j]), line, col))
            col += j - i
            i = j
            continue
        if ch.isalpha() or ch == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            word = text[i:j]
            tokens.append(Token("kw" if word in KEYWORDS else "ident",
                                word, line, col))
            col += j - i
            i = j
            continue
        for op in OPERATORS:
            if text.startswith(op, i):
                tokens.append(Token("op", op, line, col))
                i += len(op)
                col += len(op)
                break
        else:
            raise ParseError("unexpected character %r at line %d col %d"
                             % (ch, line, col))
    tokens.append(Token("eof", None, line, col))
    return tokens


class Parser(object):
    """Recursive-descent parser for the imperative language."""

    def __init__(self, text):
        self.tokens = tokenize(text)
        self.pos = 0

    # -- token helpers ----------------------------------------------------
    @property
    def current(self):
        return self.tokens[self.pos]

    def at(self, kind, value=None):
        token = self.current
        return token.kind == kind and (value is None or token.value == value)

    def accept(self, kind, value=None):
        if self.at(kind, value):
            self.pos += 1
            return self.tokens[self.pos - 1]
        return None

    def expect(self, kind, value=None):
        token = self.accept(kind, value)
        if token is None:
            raise ParseError("expected %s%s but found %r at line %d col %d"
                             % (kind, "" if value is None else " %r" % (value,),
                                self.current.value, self.current.line,
                                self.current.col))
        return token

    # -- statements -------------------------------------------------------
    def parse_program(self):
        stmts = []
        while not self.at("eof"):
            stmts.append(self.parse_statement())
        if len(stmts) == 1 and isinstance(stmts[0], Sequence):
            return stmts[0]
        return Sequence(stmts)

    def parse_block(self):
        self.expect("op", "{")
        stmts = []
        while not self.at("op", "}"):
            if self.at("eof"):
                raise ParseError("unterminated block")
            stmts.append(self.parse_statement())
        self.expect("op", "}")
        return Sequence(stmts)

    def parse_body(self):
        """A block, or a single statement used as a body."""
        if self.at("op", "{"):
            return self.parse_block()
        return self.parse_statement()

    def parse_statement(self):
        if self.at("op", "{"):
            return self.parse_block()
        if self.at("op", ";"):
            self.pos += 1
            return Sequence([])
        if self.at("kw", "var"):
            self.pos += 1
            name = self.expect("ident").value
            self.expect("op", "=")
            expr = self.parse_expression()
            self.accept("op", ";")
            return Assign(name, expr, declaration=True)
        if self.at("kw", "if"):
            self.pos += 1
            self.expect("op", "(")
            cond = self.parse_expression()
            self.expect("op", ")")
            then_body = self.parse_body()
            else_body = None
            if self.accept("kw", "else"):
                else_body = self.parse_body()
            return If(cond, then_body, else_body)
        if self.at("kw", "while"):
            self.pos += 1
            self.expect("op", "(")
            cond = self.parse_expression()
            self.expect("op", ")")
            bound = None
            if self.accept("kw", "bound"):
                bound = self.expect("num").value
            body = self.parse_body()
            return While(cond, body, bound)
        if self.at("kw", "assert") or self.at("kw", "assume"):
            keyword = self.expect("kw").value
            self.expect("op", "(")
            cond = self.parse_expression()
            self.expect("op", ")")
            self.accept("op", ";")
            return Assert(cond) if keyword == "assert" else Assume(cond)
        if self.at("ident"):
            name = self.expect("ident").value
            self.expect("op", "=")
            expr = self.parse_expression()
            self.accept("op", ";")
            return Assign(name, expr)
        raise ParseError("unexpected token %r at line %d col %d"
                         % (self.current.value, self.current.line,
                            self.current.col))

    # -- expressions ------------------------------------------------------
    def parse_expression(self):
        return self.parse_or()

    def parse_or(self):
        node = self.parse_and()
        while self.at("kw", "or") or self.at("op", "||"):
            self.pos += 1
            node = BinOp("or", node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_not()
        while self.at("kw", "and") or self.at("op", "&&"):
            self.pos += 1
            node = BinOp("and", node, self.parse_not())
        return node

    def parse_not(self):
        if self.at("kw", "not") or self.at("op", "!"):
            self.pos += 1
            return UnOp("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        node = self.parse_additive()
        for op in ("<=", ">=", "==", "!=", "<", ">"):
            if self.at("op", op):
                self.pos += 1
                return BinOp(op, node, self.parse_additive())
        return node

    def parse_additive(self):
        node = self.parse_multiplicative()
        while self.at("op", "+") or self.at("op", "-"):
            op = self.expect("op").value
            node = BinOp(op, node, self.parse_multiplicative())
        return node

    def parse_multiplicative(self):
        node = self.parse_unary()
        while self.at("op", "*"):
            self.pos += 1
            node = BinOp("*", node, self.parse_unary())
        return node

    def parse_unary(self):
        if self.accept("op", "-"):
            return UnOp("-", self.parse_unary())
        if self.accept("op", "+"):
            return self.parse_unary()
        return self.parse_primary()

    def parse_primary(self):
        token = self.accept("num")
        if token is not None:
            return Const(token.value)
        if self.accept("kw", "true"):
            return Const(True)
        if self.accept("kw", "false"):
            return Const(False)
        token = self.accept("ident")
        if token is not None:
            return Variable(token.value)
        if self.accept("op", "("):
            node = self.parse_expression()
            self.expect("op", ")")
            return node
        raise ParseError("unexpected token %r at line %d col %d"
                         % (self.current.value, self.current.line,
                            self.current.col))


def parse_program(text):
    """Parse ``text`` and return the AST (a :class:`Sequence`)."""
    return Parser(text).parse_program()


# ===========================================================================
# 3. Horn encoding
# ===========================================================================

class HornClause(object):
    """A Horn clause ``body_1 /\\ ... /\\ body_n -> head``."""

    def __init__(self, head, body=None, label=""):
        self.head = head
        self.body = list(body or [])
        self.label = label

    def to_z3(self):
        """The clause as a single Z3 implication (useful for printing/tests)."""
        if not self.body:
            return self.head
        return z3.Implies(z3.And(*self.body) if len(self.body) > 1
                          else self.body[0], self.head)

    def __str__(self):
        body = " /\\ ".join(str(b) for b in self.body) or "true"
        return "%s -> %s%s" % (body, self.head,
                               "   // %s" % self.label if self.label else "")

    def __repr__(self):
        return "HornClause(%s)" % self


class HornEncoder(object):
    """Encode a :class:`Sequence` AST into constrained Horn clauses.

    Every program point becomes a relation ``p<k>`` over the program variables.
    ``self.clauses`` accumulates :class:`HornClause` objects; ``to_z3`` loads
    them into a :class:`z3.Fixedpoint`.
    """

    def __init__(self, program_vars=None, unroll_bounded=False):
        self.program_vars = list(program_vars or [])
        self.unroll_bounded = unroll_bounded
        self.clauses = []
        self.relations = []
        self.loop_relations = []
        self.entry_relation = None
        self.exit_relation = None
        self._counter = 0
        self._error = z3.Function("Error", z3.BoolSort())
        self._pre = []
        self._post = []

    # -- plumbing ---------------------------------------------------------
    def error(self):
        """The 0-ary ``Error`` relation queried to decide safety."""
        return self._error

    def _setup_vars(self):
        self._pre = [z3.Int(name) for name in self.program_vars]
        self._post = [z3.Int(name + "!next") for name in self.program_vars]

    @property
    def pre_vars(self):
        return list(self._pre)

    @property
    def post_vars(self):
        return list(self._post)

    def new_relation(self, prefix="p"):
        """Declare a fresh program-point relation over the program variables."""
        name = "%s%d" % (prefix, self._counter)
        self._counter += 1
        sorts = [z3.IntSort()] * len(self.program_vars) + [z3.BoolSort()]
        relation = z3.Function(name, *sorts)
        self.relations.append(relation)
        return relation

    def _env(self, variables):
        return dict(zip(self.program_vars, variables))

    def _frame(self, updated=None):
        """Equalities ``x!next == x`` for every variable except ``updated``."""
        return [post == pre
                for name, pre, post in zip(self.program_vars, self._pre, self._post)
                if name != updated]

    def _add(self, head, body, label=""):
        clause = HornClause(head, body, label)
        self.clauses.append(clause)
        return clause

    def _cond(self, expr, variables):
        value = expr.to_z3(self._env(variables))
        if z3.is_int(value) or (hasattr(value, "sort") and value.sort() == z3.IntSort()):
            # Allow C-style "non-zero is true" conditions.
            return value != 0
        return value

    # -- statement dispatch ----------------------------------------------
    def encode_program(self, ast):
        """Encode ``ast`` and return the list of :class:`HornClause` objects."""
        if not self.program_vars:
            self.program_vars = collect_variables(ast)
        self._setup_vars()
        self.clauses = []
        self.relations = []
        self.loop_relations = []
        self._counter = 0

        entry = self.new_relation("p_entry")
        self.entry_relation = entry
        # All variables start at 0 before the first statement runs.
        self._add(entry(*self._pre), [var == 0 for var in self._pre], "entry")
        self.exit_relation = self.encode_statement(ast, entry)
        return self.clauses

    def encode_statement(self, stmt, pre_rel):
        """Encode ``stmt`` starting from ``pre_rel``; return the post relation."""
        if isinstance(stmt, Sequence):
            current = pre_rel
            for sub in stmt.stmts:
                current = self.encode_statement(sub, current)
            return current
        if isinstance(stmt, Assign):
            post_rel = self.new_relation("p")
            self.encode_assignment(stmt, pre_rel, post_rel)
            return post_rel
        if isinstance(stmt, If):
            post_rel = self.new_relation("p")
            self.encode_branch(stmt, pre_rel, post_rel)
            return post_rel
        if isinstance(stmt, While):
            loop_rel = self.new_relation("loop")
            self.loop_relations.append(loop_rel)
            return self.encode_loop(stmt, loop_rel, pre_rel)
        if isinstance(stmt, Assert):
            self.encode_assertion(stmt, pre_rel)
            post_rel = self.new_relation("p")
            self._add(post_rel(*self._pre),
                      [pre_rel(*self._pre), self._cond(stmt.cond, self._pre)],
                      "assert-holds")
            return post_rel
        if isinstance(stmt, Assume):
            post_rel = self.new_relation("p")
            self._add(post_rel(*self._pre),
                      [pre_rel(*self._pre), self._cond(stmt.cond, self._pre)],
                      "assume")
            return post_rel
        raise TypeError("cannot encode statement %r" % (stmt,))

    # -- individual constructs -------------------------------------------
    def encode_assignment(self, assign, pre_rel, post_rel):
        """``pre_rel(X) /\\ X' = X[v := e] -> post_rel(X')``."""
        if assign.var_name not in self.program_vars:
            raise KeyError("assignment to unknown variable %r" % assign.var_name)
        index = self.program_vars.index(assign.var_name)
        value = assign.expr.to_z3(self._env(self._pre))
        body = [pre_rel(*self._pre), self._post[index] == value]
        body.extend(self._frame(updated=assign.var_name))
        return self._add(post_rel(*self._post), body,
                         "assign %s" % assign.var_name)

    def encode_branch(self, if_node, pre_rel, post_rel):
        """Two paths: ``cond /\\ then_body`` and ``~cond /\\ else_body``."""
        cond = self._cond(if_node.cond, self._pre)

        then_entry = self.new_relation("then")
        self._add(then_entry(*self._pre), [pre_rel(*self._pre), cond],
                  "if-then-guard")
        then_exit = self.encode_statement(if_node.then_body, then_entry)
        self._add(post_rel(*self._pre), [then_exit(*self._pre)], "if-then-join")

        else_entry = self.new_relation("else")
        self._add(else_entry(*self._pre), [pre_rel(*self._pre), z3.Not(cond)],
                  "if-else-guard")
        if if_node.else_body is None:
            else_exit = else_entry
        else:
            else_exit = self.encode_statement(if_node.else_body, else_entry)
        self._add(post_rel(*self._pre), [else_exit(*self._pre)], "if-else-join")
        return post_rel

    def encode_loop(self, while_node, loop_rel, pre_rel=None, post_rel=None):
        """Recursive clause pair for a ``while`` loop.

        ``pre_rel(X) -> loop_rel(X)`` (entry), ``loop_rel(X) /\\ cond /\\ body ->
        loop_rel(X')`` (back edge, via the body's clauses) and
        ``loop_rel(X) /\\ ~cond -> post_rel(X)`` (exit).

        When the encoder was built with ``unroll_bounded=True`` and the loop
        carries a ``bound``, the loop is unrolled that many times instead, which
        yields an under-approximation useful for bug hunting.
        """
        if pre_rel is None:
            pre_rel = self.new_relation("p_pre")
            self._add(pre_rel(*self._pre), [], "loop-entry-any")
        if post_rel is None:
            post_rel = self.new_relation("p")
        cond = self._cond(while_node.cond, self._pre)

        if self.unroll_bounded and while_node.bound is not None:
            current = pre_rel
            for k in range(while_node.bound):
                body_entry = self.new_relation("body")
                self._add(body_entry(*self._pre), [current(*self._pre), cond],
                          "unroll-%d-guard" % k)
                body_exit = self.encode_statement(while_node.body, body_entry)
                self._add(post_rel(*self._pre), [current(*self._pre),
                                                 z3.Not(cond)],
                          "unroll-%d-exit" % k)
                current = body_exit
            self._add(post_rel(*self._pre), [current(*self._pre)],
                      "unroll-cutoff")
            return post_rel

        self._add(loop_rel(*self._pre), [pre_rel(*self._pre)], "loop-entry")
        body_entry = self.new_relation("body")
        self._add(body_entry(*self._pre), [loop_rel(*self._pre), cond],
                  "loop-guard")
        body_exit = self.encode_statement(while_node.body, body_entry)
        self._add(loop_rel(*self._pre), [body_exit(*self._pre)], "loop-back")
        self._add(post_rel(*self._pre), [loop_rel(*self._pre), z3.Not(cond)],
                  "loop-exit")
        return post_rel

    def encode_assertion(self, assert_node, pre_rel):
        """``pre_rel(X) /\\ ~cond -> Error``."""
        cond = self._cond(assert_node.cond, self._pre)
        return self._add(self._error(),
                         [pre_rel(*self._pre), z3.Not(cond)], "assert")

    # -- Z3 hand-off ------------------------------------------------------
    def to_z3(self, program_vars=None, engine="spacer"):
        """Load every encoded clause into a fresh :class:`z3.Fixedpoint`."""
        if program_vars is not None and list(program_vars) != self.program_vars:
            raise ValueError("program_vars %r do not match the encoded program %r"
                             % (list(program_vars), self.program_vars))
        fp = z3.Fixedpoint()
        fp.set(engine=engine)
        fp.register_relation(*(self.relations + [self._error]))
        if self._pre or self._post:
            fp.declare_var(*(self._pre + self._post))
        for clause in self.clauses:
            if clause.body:
                fp.rule(clause.head, clause.body)
            else:
                fp.rule(clause.head)
        return fp

    def validate_clauses(self):
        """Sanity-check every clause; returns the number of clauses checked.

        A clause whose body is unsatisfiable can never fire, which almost always
        means the encoding is wrong, so the check catches encoder bugs early.
        Relation applications are replaced by ``True`` since only the arithmetic
        part of the body is checked.
        """
        solver = z3.Solver()
        checked = 0
        for clause in self.clauses:
            constraints = [b for b in clause.body if not self._is_relation(b)]
            solver.push()
            solver.add(*constraints)
            if solver.check() == z3.unsat:
                solver.pop()
                raise AssertionError("clause body is unsatisfiable: %s" % clause)
            solver.pop()
            checked += 1
        return checked

    def _is_relation(self, expr):
        if not z3.is_app(expr):
            return False
        decl = expr.decl()
        return decl.kind() == z3.Z3_OP_UNINTERPRETED \
            and decl.range() == z3.BoolSort()

    @property
    def num_clauses(self):
        return len(self.clauses)

    @property
    def num_relations(self):
        # Program-point relations plus the Error relation.
        return len(self.relations) + 1


# ===========================================================================
# 4. Verification front-end
# ===========================================================================

def translate_program(text, unroll_bounded=False):
    """Parse and encode ``text``; return ``(ast, encoder)``."""
    ast = parse_program(text)
    encoder = HornEncoder(unroll_bounded=unroll_bounded)
    encoder.encode_program(ast)
    return ast, encoder


class HornVerifier(object):
    """Translate an imperative program and decide its safety with Spacer."""

    def __init__(self, text, unroll_bounded=False):
        self.text = text
        self.unroll_bounded = unroll_bounded
        self.ast = None
        self.encoder = None
        self.fp = None
        self.answer = None

    def translate(self):
        """Parse + encode + build the Z3 fixedpoint (no solving yet)."""
        self.ast, self.encoder = translate_program(self.text, self.unroll_bounded)
        self.encoder.validate_clauses()
        self.fp = self.encoder.to_z3()
        return self.encoder

    def verify(self):
        """Return ``{"safe", "num_clauses", "num_relations", ...}``."""
        if self.encoder is None:
            self.translate()
        result = self.fp.query(self.encoder.error())
        safe = result == z3.unsat
        invariants = {}
        if safe:
            try:
                self.answer = self.fp.get_answer()
                definitions = extract_relation_definitions(self.answer)
            except z3.Z3Exception:  # pragma: no cover - defensive
                definitions = {}
            for relation in self.encoder.loop_relations:
                definition = definitions.get(relation.name())
                if definition is not None:
                    invariants[relation.name()] = str(z3.simplify(definition))
        return {
            "safe": safe,
            "result": str(result),
            "num_clauses": self.encoder.num_clauses,
            "num_relations": self.encoder.num_relations,
            "num_loops": len(self.encoder.loop_relations),
            "loop_invariants": invariants,
            "variables": list(self.encoder.program_vars),
        }


def verify_program(text):
    """Parse, encode and verify an imperative program in one call."""
    return HornVerifier(text).verify()


# ===========================================================================
# 5. Benchmark programs
# ===========================================================================

PROGRAMS = [
    ("simple_counter", """
        // count up to ten, then check we landed exactly on ten
        var x = 0;
        while (x < 10) { x = x + 1; }
        assert(x == 10)
    """),
    ("sum_accumulator", """
        var s = 0;
        var i = 0;
        while (i < 5) {
            s = s + i;
            i = i + 1;
        }
        assert(s >= 0)
    """),
    ("branch_test", """
        var x = 5;
        if (x > 3) { x = x - 1; } else { x = x + 1; }
        assert(x >= 0)
    """),
    ("unsafe_loop", """
        // x leaves the loop at 100, so x < 50 must fail
        var x = 0;
        while (x < 100) { x = x + 2; }
        assert(x < 50)
    """),
    ("nested_arithmetic", """
        var a = 1;
        var b = 2;
        a = a + b;
        b = a * 2;
        assert(b == 6)
    """),
]


def run_translation_batch(programs=None):
    """Translate and verify every program, returning a metrics dictionary."""
    programs = PROGRAMS if programs is None else programs
    total_clauses = 0
    verified = 0
    unsafe = 0
    invariants = 0
    translation_time = 0.0
    details = []

    for name, text in programs:
        verifier = HornVerifier(text)
        start = time.time()
        encoder = verifier.translate()
        translation_time += time.time() - start
        total_clauses += encoder.num_clauses

        result = verifier.verify()
        if result["safe"]:
            verified += 1
        else:
            unsafe += 1
        invariants += len(result["loop_invariants"])
        result["name"] = name
        details.append(result)

    return {
        "HORN_CLAUSES_GENERATED": total_clauses,
        "HORN_PROGRAMS_VERIFIED": verified,
        "HORN_PROGRAMS_UNSAFE": unsafe,
        "HORN_LOOP_INVARIANTS": invariants,
        "HORN_TRANSLATION_TIME": round(translation_time, 2),
        "details": details,
    }

